import urllib.request, concurrent.futures, re, zipfile, io, xml.etree.ElementTree as ET
urls = {
'cueb':'https://yjs.cueb.edu.cn/zsks/zsdt/8a097e700ccd40d9ab314869ab3e5f55.htm',
'ruc':'https://econ.ruc.edu.cn/jxgl/xsxyjs/zsxb/78034bbab7084ec28daa62aadb5f6e57.htm',
'btbu':'https://eco.btbu.edu.cn/docs/2026-09/76c8c279b5104c90a0f0381d7b1ab91d.xlsx'
}
def run(item):
 k,u=item
 try:
  data=urllib.request.urlopen(u,timeout=15).read()
  if k=='btbu':
   z=zipfile.ZipFile(io.BytesIO(data)); ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
   strings=[''.join(n.itertext()) for n in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',ns)]
   out='\\n'.join(strings)
  else:
   html=data.decode('utf-8','replace'); html=re.sub(r'<(script|style)\\b["'^>]*>.*?</'"\\1>','',html,flags=re.S)
   out=re.sub(r'<["'^>]+>'"','\\n',html)
   out='\\n'.join(x.strip() for x in out.splitlines() if x.strip())
  return k,out[-14000:]
 except Exception as e:return k,str(e)
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
 for k,out in pool.map(run,urls.items()):print(k+'\\n'+out+'\\n')
PY"

